def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# Compute F_k for k=2 up to k=125
fib_numbers = {}
for k in range(2, 126):
    fib_numbers[k] = fibonacci(k)

# Print the first few and the last few to verify calculation size
print("F_2:", fib_numbers[2])
print("F_3:", fib_numbers[3])
print("F_4:", fib_numbers[4])
print("F_5:", fib_numbers[5])
print("F_10:", fib_numbers[10])
print("F_20:", fib_numbers[20])
print("F_125:", fib_numbers[125])

